package com.sicairos.workstation;

import android.app.Activity;
import android.app.AlertDialog;
import android.content.Intent;
import android.net.Uri;
import android.os.Bundle;
import android.webkit.*;
import android.widget.*;

public class MainActivity extends Activity {
    private WebView workspace, printView;
    private NativeGoogle google;
    private WorkspaceNativeTools nativeTools;
    private String pendingText;
    private boolean sharingText;
    private int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
    private boolean internal(Uri uri){return uri!=null && "https".equals(uri.getScheme()) && "209connect.com".equals(uri.getHost()) && uri.getUserInfo()==null && (uri.getPort()==-1||uri.getPort()==443) && java.util.Arrays.asList("/members/app.html","/members/guest.html","/members/native-google.html","/login.html","/recover.html","/workspace-start.html","/members/install.html","/android-download.html").contains(uri.getPath());}
    private void external(Uri uri){if(uri==null||!"https".equals(uri.getScheme())||uri.getUserInfo()!=null)return;new AlertDialog.Builder(this).setTitle("Open a separate browser?").setMessage("External pages open separately from your workspace.").setPositiveButton("Open browser",(d,w)->{try{startActivity(new Intent(Intent.ACTION_VIEW,uri));}catch(Exception e){Toast.makeText(this,"No browser available",Toast.LENGTH_LONG).show();}}).setNegativeButton("Stay here",null).show();}
    private void openPage(String url){
        if(!internal(Uri.parse(url)))return;
        if(workspace==null){workspace=new WebView(this);WebSettings s=workspace.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);CookieManager.getInstance().setAcceptThirdPartyCookies(workspace,false);nativeTools=new WorkspaceNativeTools(this,()->workspace);workspace.setWebChromeClient(nativeTools);workspace.addJavascriptInterface(new Output(),"WorkstationAndroid");
            workspace.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){Uri target=request.getUrl();if(request.isForMainFrame()&&"workstation-print".equals(target.getScheme())&&"current".equals(target.getHost())){nativeTools.printPreview();return true;}if(internal(target))return false;if(request.isForMainFrame()){if(internal(Uri.parse(view.getUrl()==null?"":view.getUrl()))&&NativeGoogle.authorizeNavigation(target))google.start();else external(target);}return true;}@Override public void onPageStarted(WebView view,String url,android.graphics.Bitmap icon){nativeTools.cancelChooser();}@Override public void onPageFinished(WebView view,String url){nativeTools.markNative(view);google.deliver();}@Override public void onReceivedError(WebView view,WebResourceRequest request,WebResourceError error){if(request.isForMainFrame()&&!isFinishing())new AlertDialog.Builder(MainActivity.this).setTitle("Workspace could not load").setMessage("Check your connection, then retry. Your saved account records have not been replaced. Offline saving is not available.").setPositiveButton("Retry",(d,w)->view.reload()).setNegativeButton("Close",null).show();}});
            getWindow().setSoftInputMode(android.view.WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);
            if(android.os.Build.VERSION.SDK_INT>=30){getWindow().setDecorFitsSystemWindows(false);workspace.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets safe=insets.getInsets(android.view.WindowInsets.Type.systemBars()|android.view.WindowInsets.Type.displayCutout()|android.view.WindowInsets.Type.ime());v.setPadding(safe.left,safe.top,safe.right,safe.bottom);return insets;});}else workspace.setFitsSystemWindows(true);
        }
        if(workspace.getParent()==null)setContentView(workspace);workspace.requestApplyInsets();workspace.loadUrl(url);
    }
    private boolean shareOrigin(WebView view){return view!=null&&view==workspace&&view.getParent()!=null&&view.getUrl()!=null&&internal(Uri.parse(view.getUrl()))&&"/members/app.html".equals(Uri.parse(view.getUrl()).getPath())&&!isFinishing()&&!isDestroyed();}
    private void shareContext(WebView view,String context,Runnable success){if(!shareOrigin(view))return;view.evaluateJavascript("(window.WorkstationApp&&!window.WorkstationApp.busy)?String(window.WorkstationApp.context):null",result->{if(shareOrigin(view)&&org.json.JSONObject.quote(context).equals(result))success.run();else if(!isFinishing())Toast.makeText(this,"Account or day changed. Review the current draft again.",Toast.LENGTH_LONG).show();});}
    private class Output {
        @JavascriptInterface public void shareText(String value,String context){if(value==null||value.trim().isEmpty()||value.length()>50000||context==null||context.length()>200)return;runOnUiThread(()->{if(sharingText||!shareOrigin(workspace))return;final WebView origin=workspace;sharingText=true;shareContext(origin,context,()->{ScrollView scroll=new ScrollView(MainActivity.this);TextView preview=new TextView(MainActivity.this);preview.setText(value);preview.setTextIsSelectable(true);preview.setPadding(dp(16),dp(12),dp(16),dp(12));scroll.addView(preview);new AlertDialog.Builder(MainActivity.this).setTitle("Share this Creator text?").setMessage("Review the exact text. Your chosen app controls what happens next; Workstation cannot confirm publication.").setView(scroll).setNegativeButton("Cancel",null).setPositiveButton("Choose destination",(d,w)->shareContext(origin,context,()->{try{Intent send=new Intent(Intent.ACTION_SEND);send.setType("text/plain");send.putExtra(Intent.EXTRA_TEXT,value);startActivity(Intent.createChooser(send,"Share Creator text"));}catch(Exception e){Toast.makeText(MainActivity.this,"No sharing destination is available. Use Copy in Workstation.",Toast.LENGTH_LONG).show();}})).setOnDismissListener(d->sharingText=false).show();});new android.os.Handler(android.os.Looper.getMainLooper()).postDelayed(()->{if(!isFinishing())sharingText=false;},30000);});}
        @JavascriptInterface public void printHtml(String html){if(html==null||html.length()>1000000)return;runOnUiThread(()->{if(workspace==null||!internal(Uri.parse(workspace.getUrl())))return;new AlertDialog.Builder(MainActivity.this).setTitle("Print or save a private copy?").setMessage("The selected content will be sent to your chosen print or PDF destination. Keep private copies secure.").setPositiveButton("Continue",(d,w)->{if(printView!=null)printView.destroy();printView=new WebView(MainActivity.this);printView.getSettings().setJavaScriptEnabled(false);printView.setWebViewClient(new WebViewClient(){@Override public void onPageFinished(WebView view,String url){android.print.PrintManager manager=(android.print.PrintManager)getSystemService(PRINT_SERVICE);if(manager!=null)manager.print("209 private copy",view.createPrintDocumentAdapter("209 private copy"),new android.print.PrintAttributes.Builder().build());}});printView.loadDataWithBaseURL(null,html,"text/html","UTF-8",null);}).setNegativeButton("Cancel",null).show();});}
        @JavascriptInterface public void saveText(String name,String value){if(value==null||value.length()>1000000)return;runOnUiThread(()->{if(workspace==null||!internal(Uri.parse(workspace.getUrl()))||pendingText!=null)return;pendingText=value;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("text/plain");i.putExtra(Intent.EXTRA_TITLE,name!=null&&name.matches("[A-Za-z0-9._-]{1,100}")?name:"209-journal.txt");try{startActivityForResult(i,209);}catch(Exception e){pendingText=null;Toast.makeText(MainActivity.this,"No document destination available",Toast.LENGTH_LONG).show();}});}
    }
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==WorkspaceNativeTools.PICK_DOCUMENT){if(nativeTools!=null)nativeTools.receive(result,data);return;}if(request!=209)return;String value=pendingText;pendingText=null;if(result==RESULT_OK&&data!=null&&data.getData()!=null&&value!=null){try(java.io.OutputStream stream=getContentResolver().openOutputStream(data.getData())){if(stream==null)throw new java.io.IOException();stream.write(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));Toast.makeText(this,"Copy saved",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"Could not save the copy. Your workspace is unchanged.",Toast.LENGTH_LONG).show();}}}
    @Override public void onCreate(Bundle state){super.onCreate(state);google=new NativeGoogle(this,new NativeGoogle.Host(){public void openHandoff(){openPage("https://209connect.com/members/native-google.html");}public WebView view(){return workspace;}});if(android.os.Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::onBackPressed);openPage("https://209connect.com/members/app.html#today");google.handle(getIntent());}
    @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);google.handle(intent);}
    @Override public void onBackPressed(){if(workspace!=null&&workspace.getParent()!=null){if(workspace.canGoBack()){workspace.goBack();return;}new AlertDialog.Builder(this).setTitle("Leave Workstation?").setMessage("Save selected day before leaving. Unsaved changes may be lost.").setPositiveButton("Leave",(d,w)->finish()).setNegativeButton("Stay",null).show();}else finish();}
    @Override protected void onPause(){if(workspace!=null)workspace.onPause();super.onPause();}
    @Override protected void onResume(){super.onResume();if(workspace!=null)workspace.onResume();}
    @Override protected void onDestroy(){pendingText=null;if(nativeTools!=null)nativeTools.close();if(google!=null)google.close();if(workspace!=null){workspace.removeJavascriptInterface("WorkstationAndroid");workspace.destroy();}if(printView!=null)printView.destroy();super.onDestroy();}
}
